package com.bank.batch;

import java.math.BigDecimal;
import java.util.logging.*;

public class VarargsMainDemo {
    private static final Logger log = Logger.getLogger("BankLog");
    static {
        Handler h = new ConsoleHandler();
        h.setFormatter(new SimpleFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
        log.setLevel(Level.ALL);
    }

    // Entry point declared with VARARGS. Compiles to main(String[]) — the JVM accepts it.
    public static void main(String... args) {
        // 'args' behaves EXACTLY like a String[] here: index + length, empty not null.
        log.info(() -> "Entry via String... args — arg count = " + args.length);
        String accountId = args.length > 0 ? args[0] : "SAV2001";
        BigDecimal amount = args.length > 1 ? new BigDecimal(args[1]) : new BigDecimal("50000.00");
        log.info(() -> "Settling Rs." + amount + " for account " + accountId);

        // Minor convenience: we can call main() ourselves with LOOSE strings (no array needed).
        if (args.length == 0) {
            log.info("Re-invoking main with loose varargs arguments (test-style call):");
            main("CUR3001", "75000.00"); // compiler bundles into String[] automatically
        }
    }
}
